<?php
require_once __DIR__.'/db.php';require_once __DIR__.'/includes/functions.php';require_role(['admin','manager']);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$status=$_POST['status'];if(in_array($status,['approved','rejected'],true)){$st=$pdo->prepare("UPDATE applications SET status=?,reviewed_by=?,reviewed_at=NOW() WHERE id=? AND status='pending'");$st->execute([$status,current_user_id(),$id]);flash('Вазъияти дархост нав шуд.');}redirect('applications.php');}
$rows=$pdo->query("SELECT a.*,u.full_name,s.student_number,d.name dormitory_name FROM applications a JOIN students s ON s.id=a.student_id JOIN users u ON u.id=s.user_id JOIN dormitories d ON d.id=a.dormitory_id ORDER BY a.submitted_at DESC")->fetchAll();$pageTitle='Дархостҳо';require __DIR__.'/includes/header.php';?>
<h1>Дархостҳои хобгоҳ</h1><div class="table-wrap"><table><tr><th>ID</th><th>Донишҷӯ</th><th>Рақам</th><th>Хобгоҳ</th><th>Сана</th><th>Вазъият</th><th>Амалиёт</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['full_name'])?></td><td><?=e($r['student_number'])?></td><td><?=e($r['dormitory_name'])?></td><td><?=e($r['submitted_at'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='pending'):?><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="status" value="approved">Тасдиқ</button><button class="danger" name="status" value="rejected">Рад</button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/includes/footer.php';?>
